import Foundation
import NextCupKit
import SwiftData

/// The bundled roaster catalog (`catalog.json`): facts about real roasters and
/// coffees, each with the date they were checked. Line-ups change, so the screens
/// show that date. Starting recipes are generated by `StarterRecipes`, never stored.
struct RoasterCatalog: Decodable, Equatable, Sendable {
  struct Coffee: Decodable, Equatable, Identifiable, Sendable {
    var key: String
    var name: String
    var originCountry: String?
    var region: String?
    var process: String?
    var roastLevel: RoastLevel?
    var isBlend: Bool
    var isDecaf: Bool
    var flavorNotes: [String]?
    var source: URL?

    var id: String { key }
  }

  struct Roaster: Decodable, Equatable, Identifiable, Sendable {
    var key: String
    var name: String
    var city: String
    var region: String
    var country: String
    var website: URL
    var kind: String
    var coffees: [Coffee]

    var id: String { key }
    var place: String { [city, region].joined(separator: ", ") }
  }

  enum CatalogError: Error, Equatable {
    case missingResource
    case invalid(String)
  }

  var version: Int
  var checkedOn: String
  var note: String
  var roasters: [Roaster]

  /// Parses and validates: unknown roast levels fail the decode, and keys must be
  /// unique and links must be https so a bad bundle fails in tests, not on screen.
  init(data: Data) throws {
    self = try JSONDecoder().decode(RoasterCatalog.self, from: data)
    var keys = Set<String>()
    for roaster in roasters {
      guard !roaster.name.isEmpty, roaster.website.scheme == "https",
        keys.insert(roaster.key).inserted
      else { throw CatalogError.invalid("roaster \(roaster.key)") }
      for coffee in roaster.coffees {
        guard !coffee.name.isEmpty, keys.insert(coffee.key).inserted,
          coffee.source.map({ $0.scheme == "https" }) ?? true
        else { throw CatalogError.invalid("coffee \(coffee.key)") }
      }
    }
  }

  init(bundle: Bundle = .main) throws {
    guard let url = bundle.url(forResource: "catalog", withExtension: "json") else {
      throw CatalogError.missingResource
    }
    try self.init(data: Data(contentsOf: url))
  }

  /// Loaded once; `nil` when the bundle is unreadable.
  static let shared: RoasterCatalog? = try? RoasterCatalog(bundle: .main)
}

extension RoasterCatalog.Coffee {
  /// The three starter recipes for this coffee's roast level and process.
  var starterRecipes: [StarterRecipe] {
    StarterRecipes.recipes(
      roast: roastLevel.flatMap { StarterRoast(rawValue: $0.rawValue) }, process: process)
  }
}

/// Add a catalog coffee to the bean library, and keep the starter recipe a brew
/// uses. Both reuse what exists, so tapping twice never duplicates.
@MainActor
struct CatalogService {
  let store: Store

  private var context: ModelContext { store.context }

  /// The bean (and its roaster) for a catalog coffee: an existing bean with the
  /// same name and roaster, or a new one. `created` is false when it was reused.
  func addBean(_ coffee: RoasterCatalog.Coffee, from roaster: RoasterCatalog.Roaster)
    -> Result<(bean: Bean, created: Bool), BeanError>
  {
    let beans = (try? context.fetch(FetchDescriptor<Bean>())) ?? []
    if let match = beans.first(where: {
      Self.same($0.name, coffee.name) && Self.same($0.roaster?.name ?? "", roaster.name)
    }) {
      return .success((match, false))
    }
    var fields = BeanFields()
    fields.name = coffee.name
    fields.roasterName = roaster.name
    fields.roasterCity = roaster.city
    fields.roasterWebsite = roaster.website
    fields.originCountry = coffee.originCountry ?? ""
    fields.region = coffee.region ?? ""
    fields.process = coffee.process ?? ""
    fields.roastLevel = coffee.roastLevel
    fields.flavorNotes = (coffee.flavorNotes ?? []).joined(separator: ", ")
    fields.isDecaf = coffee.isDecaf
    return BeanService(store: store).save(fields).map { ($0, true) }
  }

  /// The saved recipe for a starter recipe of this coffee, created on first use.
  func recipe(for starter: StarterRecipe, coffee: RoasterCatalog.Coffee) -> Result<
    Recipe, BeanError
  > {
    let key = "starter.\(coffee.key).\(starter.style.rawValue)"
    let recipes = (try? context.fetch(FetchDescriptor<Recipe>())) ?? []
    if let existing = recipes.first(where: { $0.builtInKey == key }) { return .success(existing) }

    let methods = (try? context.fetch(FetchDescriptor<BrewMethod>())) ?? []
    let recipe = Recipe(
      name: "\(coffee.name): \(starter.name)", doseG: starter.doseG, waterG: starter.waterG)
    recipe.tempC = starter.tempC
    recipe.totalTimeS = starter.totalTimeS
    recipe.tuningNote = starter.note
    recipe.credit = "Next Cup starting recipe"
    recipe.builtInKey = key
    recipe.method = methods.first { $0.builtInKey == starter.methodKey }
    context.insert(recipe)
    recipe.steps = starter.steps.enumerated().map { index, step in
      let model = RecipeStep(
        order: index, kind: StepKind(rawValue: step.kind) ?? .pour, startOffsetS: step.startOffsetS)
      model.targetCumulativeWaterG = step.targetCumulativeWaterG
      model.instruction = step.instruction
      return model
    }
    switch store.save() {
    case .success: return .success(recipe)
    case .failure(.saveFailed(let reason)):
      context.rollback()
      return .failure(.saveFailed(reason))
    }
  }

  private static func same(_ a: String, _ b: String) -> Bool {
    a.compare(b, options: [.caseInsensitive, .diacriticInsensitive]) == .orderedSame
  }
}
